+    trait NotLexerPartialOrd { const IS: bool = false; }
+    impl<T> NotLexerPartialOrd for LexerPartialOrdProbe<T> {}
+    impl<T: PartialOrd> LexerPartialOrdProbe<T> { const IS: bool = true; }
+
